parameters.jsonBody:
=
{{ JSON.stringify({
  model: "llama3.2:3b",

  prompt: `Você é um especialista em suporte de TI.

Classifique o chamado abaixo usando exatamente uma categoria e uma prioridade.

CATEGORIAS:
- Hardware: problemas físicos em computadores, impressoras e periféricos.
- Software: problemas em programas e aplicativos.
- Rede: problemas com internet, Wi-Fi e conectividade.
- Acesso: problemas com senhas, login, contas e permissões.

PRIORIDADES:
- Baixa: problema pequeno que não impede o trabalho.
- Média: afeta um funcionário, mas permite continuar trabalhando.
- Alta: impede o trabalho de um funcionário ou setor.
- Crítica: interrompe um serviço essencial para toda a empresa.

EXEMPLOS:
Problema: Minha senha do e-mail não funciona.
Classificação: {"categoria":"Acesso","prioridade":"Alta"}

Problema: A internet de toda a empresa caiu.
Classificação: {"categoria":"Rede","prioridade":"Crítica"}

Problema: O mouse está com pequenos problemas, mas ainda funciona.
Classificação: {"categoria":"Hardware","prioridade":"Baixa"}

AGORA CLASSIFIQUE:
Título: ${$json.titulo}
Descrição: ${$json.descricao}

Retorne somente categoria e prioridade em JSON.`,

  stream: false,

  format: {
    type: "object",
    properties: {
      categoria: {
        type: "string",
        enum: ["Hardware", "Software", "Rede", "Acesso"]
      },
      prioridade: {
        type: "string",
        enum: ["Baixa", "Média", "Alta", "Crítica"]
      }
    },
    required: ["categoria", "prioridade"],
    additionalProperties: false
  },

  options: {
    temperature: 0
  }
}) }}

parameters.jsCode:
const resposta = $input.first().json.response;

const classificacao = JSON.parse(resposta);

const chamado = $('Edit Fields').first().json;

const categorias = ['Hardware', 'Software', 'Rede', 'Acesso'];
const prioridades = ['Baixa', 'Média', 'Alta', 'Crítica'];

if (!categorias.includes(classificacao.categoria)) {
  throw new Error('Categoria inválida retornada pela IA');
}

if (!prioridades.includes(classificacao.prioridade)) {
  throw new Error('Prioridade inválida retornada pela IA');
}

return [
  {
    json: {
      titulo: chamado.titulo,
      descricao: chamado.descricao,
      categoria: classificacao.categoria,
      prioridade: classificacao.prioridade
    }
  }
];

